import { createClient } from "@/lib/supabase/server";
import { getAnthropicClient } from "@/lib/anthropic/client";
import { NextResponse } from "next/server";
import Anthropic from "@anthropic-ai/sdk";
import { z } from "zod";
import { createAdminClient } from "@/lib/supabase/admin";

// system prompt for anthropic to generate a care profile for a plant based on plant species, needs to return only a json object

const SYSTEM_PROMPT = `You are a horticulture expert. Given a plant species, produce a concise, practical care profile.

RETURN ONLY A JSON OBJECT — NO MARKDOWN, NO CODE FENCES, NO PREAMBLE OR EXPLANATION — MATCHING EXACTLY THIS SHAPE:
{
  "watering": { "interval_days_summer": int, "interval_days_winter": int, "method": string, "signs_thirsty": string, "signs_overwatered": string },
  "fertilizing": { "interval_days_growing_season": int, "interval_days_dormant": int or null, "type": string },
  "mist": { "interval_days": int or null, "method": string or null, "notes": string },
  "light": { "level": "bright indirect" | "low" | "direct", "notes": string },
  "humidity": { "level": "low" | "medium" | "high", "notes": string },
  "temperature_range_c": [int, int],
  "toxicity": { "pets": boolean, "notes": string },
  "common_problems": [ { "symptom": string, "cause": string, "fix": string } ],
  "rotation_days": int
}

Rules:
- All intervals are whole numbers of days. "interval_days_dormant" may be null if the plant should not be fertilized while dormant.
- mist is optional; if the plant doesn't benefit from misting, set "interval_days" to null.
- "temperature_range_c" is [min, max] in Celsius.
- "rotation_days" is how often to rotate the pot for even growth (use 0 if unimportant).
- "toxicity.pets" is true if the plant is toxic to pets or domestic animals.
- Provide 2 to 4 entries in "common_problems".
- Output valid JSON and nothing else.`;

export async function POST(request) {
    // first check if there is already a care profile for this plant in the database, if so return it, otherwise generate a new one using anthropic

    const admin = createAdminClient();
    const userSupabase = await createClient();
    const { data: { user } } = await userSupabase.auth.getUser();

    if (!user) {
        return NextResponse.json({ error: "Unauthorized" }, { status: 401 });
    }

    const { species, custom_name } = await request.json();

    // check if care profile already exists in database
    const { data: existingProfile, error: fetchError } = await admin
        .from("care_profiles")
        .select("*")
        .eq("species_scientific", species.scientific_name)
        .single();

    if (existingProfile?.profile_json) {
        return NextResponse.json(existingProfile.profile_json);
    }

    // create a zod schema to validate the response from anthropic

    const responseSchema = z.object({
        watering: z.object({
            interval_days_summer: z.number().int(),
            interval_days_winter: z.number().int(),
            method: z.string(),
            signs_thirsty: z.string(),
            signs_overwatered: z.string(),
        }),
        fertilizing: z.object({
            interval_days_growing_season: z.number().int(),
            interval_days_dormant: z.number().int().nullable(),
            type: z.string(),
        }),
        mist: z.object({
            interval_days: z.number().int().nullable(),
            method: z.string().nullable(),
            notes: z.string(),
        }),
        light: z.object({
            level: z.enum(["bright indirect", "low", "direct"]),
            notes: z.string(),
        }),
        humidity: z.object({
            level: z.enum(["low", "medium", "high"]),
            notes: z.string(),
        }),
        temperature_range_c: z.tuple([z.number().int(), z.number().int()]),
        toxicity: z.object({
            pets: z.boolean(),
            notes: z.string(),
        }),
        common_problems: z.array(
            z.object({
                symptom: z.string(),
                cause: z.string(),
                fix: z.string(),
            })
        ).min(2).max(4),
        rotation_days: z.number().int(),
    });

    const anthropicClient = getAnthropicClient();

    try {
        const anthropicResponse = await anthropicClient.messages.create({
            model: process.env.ANTHROPIC_AI_MODEL,
            max_tokens: 1024,
            system: [
                {
                    type: "text",
                    text: SYSTEM_PROMPT,
                    cache_control: { type: "ephemeral" }
                }
            ],
            messages: [
                {
                    role: "user",
                    content: [
                        {
                            type: "text",
                            text: `Generate a care profile for the plant species "${species.scientific_name || custom_name}". Return only a JSON object matching the specified shape.`,
                        }
                    ],
                }
            ],
        });

        const rawResponse = anthropicResponse.content[0]?.text;

        if (!rawResponse) {
            return NextResponse.json({ error: "No response from Anthropic API" }, { status: 500 });
        }

        const cleanedResponse = rawResponse.replace(/```json|```/g, "").trim();

        // validate the response using zod
        const parsedProfile = responseSchema.safeParse(JSON.parse(cleanedResponse));

        if (!parsedProfile.success) {
            return NextResponse.json({ error: "Invalid care profile format from Anthropic API", details: parsedProfile.error.errors }, { status: 500 });
        }

        // store the new care profile in the database
        const { data: insertedProfile, error: insertError } = await admin
            .from("care_profiles")
            .upsert({
                species_scientific: species.scientific_name,
                profile_json: parsedProfile.data,
                source: "ai"
            })

        return NextResponse.json(parsedProfile.data);
    } catch (error) {
        const message = error instanceof Error ? error.message : String(error);

        return NextResponse.json({ error: "Unexpected error", details: message, }, { status: 500 });
    }
}

import { NextResponse } from "next/server";
import webpush from "web-push";
import { createAdminClient } from "@/lib/supabase/admin";

export const runtime = "nodejs";
export const dynamic = "force-dynamic";

webpush.setVapidDetails(
    process.env.VAPID_SUBJECT,
    process.env.NEXT_PUBLIC_VAPID_PUBLIC_KEY,
    process.env.VAPID_PRIVATE_KEY
)

const LABELS = { water: "watering", mist: "misting", rotate: "rotating", fertilize: "fertilizing" };

function localHour(timezone) {
    try {
        return Number(new Intl.DateTimeFormat("en-US", { hour: "numeric", hourCycle: "h23", timeZone: timezone }).format(new Date()));
    } catch (error) {
        return Number(new Intl.DateTimeFormat("en-US", { hour: "numeric", hourCycle: "h23" }).format(new Date()));
    }
}

export async function GET(request) {
    if (request.headers.get("authorization") !== `Bearer ${process.env.CRON_SECRET}`) {
        return NextResponse.json({ error: "Unauthorized" }, { status: 401 });
    }

    const admin = createAdminClient();
    const now = new Date();
    const cooldown = new Date(now.getTime() - 60 * 60 * 1000); // 1 hour ago

    const { data: profiles, error: profileError } = await admin.from("profiles").select("id, timezone, push_subscription, reminder_hour").not("push_subscription", "is", null);

    if (profileError) {
        console.error("Error fetching profiles:", profileError);
        return NextResponse.json({ error: "Failed to fetch profiles" }, { status: 500 });
    }

    const due = profiles.filter(profile => {
        const hour = localHour(profile.timezone);
        return profile.reminder_hour === hour;
    });

    if (!due.length) {
        return NextResponse.json({ message: "No due reminders" }, { status: 200 });
    }

    const { data: tasks, error: taskError } = await admin.from("care_tasks")
        .select("id, task_type, next_due_at, plants!inner(id, nickname, species_common, user_id)")
        .eq("paused", false)
        .lte("next_due_at", now.toISOString())
        .in("plants.user_id", due.map(profile => profile.id))
        .or(`last_notified_at.is.null,last_notified_at.lte.${cooldown.toISOString()}`);

    if (taskError) {
        console.error("Error fetching tasks:", taskError);
        return NextResponse.json({ error: "Failed to fetch tasks" }, { status: 500 });
    }

    const byUser = new Map();

    for (const task of tasks) {
        const userId = task.plants.user_id;
        if (!byUser.has(userId)) {
            byUser.set(userId, []);
        }
        byUser.get(userId).push(task);
    }

    let notificationsSent = 0;

    for (const profile of due) {
        const userTasks = byUser.get(profile.id) || [];
        if (!userTasks.length) continue;

        const firstTask = userTasks[0];
        const plantName = firstTask.plants.nickname || firstTask.plants.species_common || "your plant";
        const body = userTasks.length === 1
            ? `It's time to ${LABELS[firstTask.task_type]} ${plantName}.`
            : `You have ${userTasks.length} plants that need attention.`;

        const payload = JSON.stringify({
            title: "Your plants need attention!",
            body,
            tag: "overdue-care",
            data: { url: userTasks.length === 1 ? `/plants/${firstTask.plants.id}` : "/plants" }
        });

        try {
            await webpush.sendNotification(profile.push_subscription, payload);
            notificationsSent++;

            await admin.from("care_tasks")
                .update({ last_notified_at: new Date().toISOString() })
                .in("id", userTasks.map(task => task.id));
        } catch (error) {
            console.error(`Error sending notification to user ${profile.id}:`, error);

            if (error.statusCode === 410 || error.statusCode === 404) {
                await admin.from("profiles")
                    .update({ push_subscription: null })
                    .eq("id", profile.id);
            }
        }

    }

    return NextResponse.json({ message: `Notifications sent: ${notificationsSent}` }, { status: 200 });

}

// identifying a plant based on an image using anthropic sdk

import { createClient } from "@/lib/supabase/server";
import { getAnthropicClient } from "@/lib/anthropic/client";
import { NextResponse } from "next/server";
import Anthropic from "@anthropic-ai/sdk";
import { z } from "zod";

// system prompt for anthropic to identify a plant based on an image, needs to return only a json object

const SYSTEM_PROMPT = `You are a botanist specializing in plant identification. You are shown a single photo of a plant and must identify the most likely species.

RETURN ONLY A JSON OBJECT — NO MARKDOWN, NO CODE FENCES, NO PREAMBLE OR EXPLANATION — MATCHING EXACTLY THIS SHAPE:
{
  "primary": { "common_name": string, "scientific_name": string, "confidence": number, "type": "houseplant" | "succulent" | "cacti" | "flowering" | "tree" | "shrub" | "herb" | "edible" | "fern" | "palm" | "other" },
  "alternatives": [ { "common_name": string, "scientific_name": string, "confidence": number, "type": "houseplant" | "succulent" | "cacti" | "flowering" | "tree" | "shrub" | "herb" | "edible" | "fern" | "palm" | "other" } ],
  "visible_health_issues": [ string ],
  "note": string (optional)
}

Rules:
- "confidence" is a decimal between 0 and 1.
- "primary" is your single best guess. "alternatives" holds up to 2 other plausible species, most likely first.
- "type" is the broadest applicable category from the listed enum. Use "houseplant" for foliage plants typically grown indoors; "succulent" for non-cactus succulents (e.g. Aloe, Jade, Echeveria); "cacti" for cacti; "flowering" when blooms are the main feature; "tree" or "shrub" for woody outdoor specimens; "herb" for culinary/medicinal herbs (basil, mint, lavender); "edible" for fruit/vegetable crops; "fern" for ferns; "palm" for palms; "other" only when none fit.
- "visible_health_issues" lists visible problems (e.g. "yellowing lower leaves", "brown leaf tips", "signs of pests"). Use an empty array if none are visible.
- If the image contains no identifiable plant, set primary.confidence to 0, use primary.common_name "Unknown" with scientific_name "" and type "other", leave alternatives empty, and explain in "note".
- Prefer widely-kept houseplant species.
- Output valid JSON and nothing else.`

export async function POST(request) {
    // use zod to validate the response from anthropic

    const responseSchema = z.object({
        primary: z.object({
            common_name: z.string(),
            scientific_name: z.string(),
            confidence: z.number().min(0).max(1),
            type: z.enum(["houseplant", "succulent", "cacti", "flowering", "tree", "shrub", "herb", "edible", "fern", "palm", "other"]),
        }),
        alternatives: z.array(
            z.object({
                common_name: z.string(),
                scientific_name: z.string(),
                confidence: z.number().min(0).max(1),
                type: z.enum(["houseplant", "succulent", "cacti", "flowering", "tree", "shrub", "herb", "edible", "fern", "palm", "other"]),
            })
        ).max(2),
        visible_health_issues: z.array(z.string()),
        note: z.string().optional(),
    });

    try {
        const supabase = await createClient();
        const { data: { user } } = await supabase.auth.getUser();

        if (!user) {
            return NextResponse.json({ error: "Unauthorized" }, { status: 401 });
        }

        const { image } = await request.json();

        if (!image) {
            return NextResponse.json({ error: "Image is required" }, { status: 400 });
        }

        const anthropicClient = getAnthropicClient();

        const anthropicResponse = await anthropicClient.messages.create({
            model: process.env.ANTHROPIC_AI_MODEL,
            max_tokens: 1024,
            system: [
                {
                    type: "text",
                    text: SYSTEM_PROMPT,
                    cache_control: { type: "ephemeral" }
                }
            ],
            messages: [
                {
                    role: "user",
                    content: [
                        {
                            type: "text",
                            text: `Identify the plant in this image. Return only a JSON object matching the specified shape.`,
                            cache_control: { type: "ephemeral" }
                        },
                        {
                            type: "image",
                            source: { type: "base64", media_type: "image/jpeg", data: image },
                        }
                    ]
                }
            ]
        })

        const rawResponse = anthropicResponse.content[0].text;
        // remove markdown code fences if present
        const cleanedResponse = rawResponse.replace(/```json|```/g, "").trim();

        const parsedResponse = responseSchema.parse(JSON.parse(cleanedResponse));
        return NextResponse.json(parsedResponse);
    } catch (error) {
        const message = error instanceof Error ? error.message : String(error);

        return NextResponse.json({ error: "Unexpected error", details: message, }, { status: 500 });
    }
}

import { createClient } from "@/lib/supabase/server";
import { NextResponse } from "next/server";

export async function POST(request) {
    const supabase = await createClient();
    const { data: { user } } = await supabase.auth.getUser();

    if (!user) {
        return NextResponse.json({ error: "Unauthorized" }, { status: 401 });
    }

    const body = await request.json();

    if (!body) {
        return NextResponse.json({ error: "Request body is required" }, { status: 400 });
    }

    const { plant, careSettings, plantTasks, base64Photo } = body;

    const { data: img, error: imgError } = await supabase.storage
        .from("plant-photos")
        .upload(`${user.id}/${crypto.randomUUID()}.jpg`, Buffer.from(base64Photo, "base64"), {
            contentType: "image/jpeg",
            upsert: true,
        });

    console.log("plant tasks", plantTasks);

    try {
        const { data, error } = await supabase
            .from("plants")
            .insert({
                user_id: user.id,
                species_scientific: plant.plant_data.scientific_name,
                species_common: plant.plant_data.common_name || null,

                photo_url: img?.path || null,

                type: plant.plant_data.type || "other",

                health_issues: careSettings.common_problems || null,

                location: null,
                acquired_at: null,
                nickname: plant.custom_name || null,
            })
            .select("id")
            .single();

        if (error) {
            console.error("Error inserting plant:", error);
            return NextResponse.json({ error: "Failed to save plant" }, { status: 500 });
        }

        const { data: taskData, error: taskError } = await supabase
            .from("care_tasks")
            .insert(
                plantTasks.map((task) => ({
                    task_type: task.task_type,
                    interval_days: task.interval_days,
                    paused: task.paused,
                    next_due_at: new Date(Date.now() + task.interval_days * 24 * 60 * 60 * 1000).toISOString(),
                    plant_id: data.id,
                }))
            )

        return NextResponse.json({ message: "Plant and tasks saved successfully" }, { status: 200 });
    } catch (error) {
        console.error("Error saving plant and tasks:", error);
        return NextResponse.json({ error: "Failed to save plant and tasks" }, { status: 500 });
    }
}

// change reminder hour without re-subscribing to push notifications

import { createClient } from "@/lib/supabase/server";
import { NextResponse } from "next/server";

export async function POST(request) {
    const supabase = await createClient();
    const { data: { user }, error: userError } = await supabase.auth.getUser();

    if (!user) {
        return NextResponse.json({ error: "Unauthorized" }, { status: 401 });
    }

    const { reminderHour } = await request.json();

    if (!Number.isInteger(reminderHour) || reminderHour < 0 || reminderHour > 23) {
        return NextResponse.json({ error: "Invalid reminder time" }, { status: 400 });
    }

    const { error } = await supabase
        .from("profiles")
        .update({ reminder_hour: reminderHour, updated_at: new Date().toISOString() })
        .eq("id", user.id);

    if (error) {
        return NextResponse.json({ error: error.message }, { status: 500 });
    }

    return NextResponse.json({ message: "Reminder time updated successfully" }, { status: 200 });
}

import { createClient } from "@/lib/supabase/server";
import { NextResponse } from "next/server";

export async function POST(request) {
    const supabase = await createClient();
    const { data: { user }, error: userError } = await supabase.auth.getUser();

    if (!user) {
        return NextResponse.json({ error: "Unauthorized" }, { status: 401 });
    }

    const { subscription, timezone, reminderHour } = await request.json();

    if (!subscription?.endpoint || !subscription?.keys?.p256dh || !subscription?.keys?.auth) {
        return NextResponse.json({ error: "Invalid subscription object" }, { status: 400 });
    }

    const updateData = {
        push_subscription: subscription,
        updated_at: new Date().toISOString(),
    }

    if (timezone && Intl.supportedValuesOf('timeZone').includes(timezone)) {
        updateData.timezone = timezone;
    }

    if (Number.isInteger(reminderHour) && reminderHour >= 0 && reminderHour <= 23) {
        updateData.reminder_hour = reminderHour;
    }

    const { error } = await supabase.from("profiles").update(updateData).eq("id", user.id);

    if (error) {
        return NextResponse.json({ error: error.message }, { status: 500 });
    }

    return NextResponse.json({ message: "Subscription updated successfully" }, { status: 200 });
}

